import {
  ChangeDetectionStrategy,
  Component,
  input,
  output,
} from '@angular/core';
import { UiIconComponent, UiIconName } from '../icon/ui-icon.component';

export interface BreadcrumbItem {
  label: string;
  url?: string;
  disabled?: boolean;
  icon?: UiIconName;
}

export type BreadcrumbHomeDisplay = 'icon' | 'text' | 'icon-text';

@Component({
  selector: 'ui-breadcrumb',
  standalone: true,
  imports: [UiIconComponent],
  templateUrl: './ui-breadcrumb.component.html',
  styleUrl: './ui-breadcrumb.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class UiBreadcrumbComponent {
  items = input<BreadcrumbItem[]>([]);
  separator = input('/');
  ariaLabel = input('');
  homeDisplay = input<BreadcrumbHomeDisplay>('icon-text');
  showIcons = input(true);

  itemClick = output<BreadcrumbItem>();

  isFirst(index: number): boolean {
    return index === 0;
  }

  shouldShowIcon(item: BreadcrumbItem, index: number): boolean {
    if (!this.showIcons()) {
      return false;
    }

    if (this.isFirst(index)) {
      return (
        this.homeDisplay() === 'icon' || this.homeDisplay() === 'icon-text'
      );
    }

    return Boolean(item.icon);
  }

  shouldShowLabel(index: number): boolean {
    if (!this.isFirst(index)) {
      return true;
    }

    return this.homeDisplay() === 'text' || this.homeDisplay() === 'icon-text';
  }

  getIcon(item: BreadcrumbItem, index: number): UiIconName | null {
    if (!this.shouldShowIcon(item, index)) {
      return null;
    }

    if (this.isFirst(index)) {
      return item.icon || 'home';
    }

    return item.icon || null;
  }
}

import { InjectionToken } from '@angular/core';

export interface UiFormFieldContext {
  hasError(): boolean;
  describedBy(): string | null;
  labelId(): string | null;
}

export const UI_FORM_FIELD = new InjectionToken<UiFormFieldContext>(
  'UI_FORM_FIELD',
);

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  inject,
  input,
  output,
  signal,
} from '@angular/core';
import { ControlValueAccessor, NgControl, Validators } from '@angular/forms';
import { UI_FORM_FIELD } from '../form-field/ui-form-field.context';
import { UiFieldErrorComponent } from '../field-error/ui-field-error.component';
import { UiLabelComponent } from '../label/ui-label.component';

export interface UiRadioOption {
  label: string;
  value: string;
  disabled?: boolean;
}

export type UiRadioOrientation = 'horizontal' | 'vertical';

@Component({
  selector: 'ui-radio-group',
  standalone: true,
  imports: [UiFieldErrorComponent, UiLabelComponent],
  templateUrl: './ui-radio-group.component.html',
  styleUrl: './ui-radio-group.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class UiRadioGroupComponent implements ControlValueAccessor {
  private readonly ngControl = inject(NgControl, {
    self: true,
    optional: true,
  });
  private readonly formField = inject(UI_FORM_FIELD, { optional: true });

  id = input(`ui-radio-group-${crypto.randomUUID()}`);
  name = input<string | null>(null);
  label = input('');
  ariaLabel = input<string | null>(null);
  hideLabel = input(false);
  hideError = input(false);

  options = input<UiRadioOption[]>([]);
  orientation = input<UiRadioOrientation>('horizontal');
  allowClear = input(false);

  required = input(false);
  disabled = input(false);
  showError = input(false);
  errorMessage = input('');
  customClass = input('');
  valueInput = input<string | null>(null, { alias: 'value' });

  valueChange = output<string | null>();

  value = signal<string | null>(null);
  disabledState = signal(false);

  constructor() {
    if (this.ngControl) {
      this.ngControl.valueAccessor = this;
    }

    effect(() => {
      if (!this.ngControl) {
        this.value.set(this.valueInput());
      }
    });
  }

  isDisabled = computed(() => this.disabled() || this.disabledState());

  groupName = computed(() => this.name() || this.id());

  errorId = computed(() => `${this.id()}-error`);

  labelId = computed(() => `${this.id()}-label`);

  describedBy = computed(() => {
    if (this.formField) {
      return this.formField.describedBy();
    }

    return this.hasError() ? this.errorId() : null;
  });

  classes = computed(() =>
    [
      'ui-radio-group',
      `ui-radio-group--${this.orientation()}`,
      this.hasError() ? 'ui-radio-group--error' : '',
      this.isDisabled() ? 'ui-radio-group--disabled' : '',
      this.customClass(),
    ]
      .filter(Boolean)
      .join(' '),
  );

  hasRequired(): boolean {
    const control = this.ngControl?.control;

    return Boolean(
      this.required() || control?.hasValidator?.(Validators.required),
    );
  }

  hasError(): boolean {
    if (this.formField) {
      return this.formField.hasError();
    }

    const control = this.ngControl?.control;

    return Boolean(
      this.showError() ||
        (control?.invalid && (control.touched || control.dirty)),
    );
  }

  optionId(option: UiRadioOption, index: number): string {
    return `${this.id()}-option-${index}-${option.value}`;
  }

  isOptionDisabled(option: UiRadioOption): boolean {
    return this.isDisabled() || Boolean(option.disabled);
  }

  onChange: (value: string | null) => void = () => {};
  onTouched: () => void = () => {};

  handleClick(event: Event, option: UiRadioOption): void {
    if (this.isOptionDisabled(option)) {
      event.preventDefault();
      return;
    }

    if (this.allowClear() && this.value() === option.value) {
      event.preventDefault();
      this.value.set(null);
      this.onChange(null);
      this.valueChange.emit(null);
    }
  }

  handleChange(option: UiRadioOption): void {
    if (this.isOptionDisabled(option)) {
      return;
    }

    this.value.set(option.value);
    this.onChange(option.value);
    this.valueChange.emit(option.value);
  }

  handleBlur(): void {
    this.onTouched();
  }

  writeValue(value: string | null): void {
    this.value.set(value ?? null);
  }

  registerOnChange(fn: (value: string | null) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabledState.set(isDisabled);
  }
}

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  ElementRef,
  HostListener,
  inject,
  input,
  output,
  signal,
  viewChild,
} from '@angular/core';
import { NgStyle } from '@angular/common';
import { ControlValueAccessor, NgControl, Validators } from '@angular/forms';
import { UI_FORM_FIELD } from '../form-field/ui-form-field.context';
import { UiFieldErrorComponent } from '../field-error/ui-field-error.component';
import { UiIconComponent, UiIconName } from '../icon/ui-icon.component';
import { UiLabelComponent } from '../label/ui-label.component';

export interface UiSelectOption {
  label: string;
  value: string;
  disabled?: boolean;
  iconName?: UiIconName;
  iconLabel?: string | null;
}

export type UiSelectValue = string | string[] | null;

@Component({
  selector: 'ui-select',
  standalone: true,
  imports: [NgStyle, UiFieldErrorComponent, UiLabelComponent, UiIconComponent],
  templateUrl: './ui-select.component.html',
  styleUrl: './ui-select.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class UiSelectComponent implements ControlValueAccessor {
  private readonly host = inject(ElementRef<HTMLElement>);

  private readonly ngControl = inject(NgControl, {
    self: true,
    optional: true,
  });
  private readonly formField = inject(UI_FORM_FIELD, { optional: true });

  searchInput = viewChild<ElementRef<HTMLInputElement>>('searchInput');

  label = input('');
  ariaLabel = input<string | null>(null);
  hideLabel = input(false);
  hideError = input(false);

  id = input(`ui-select-${crypto.randomUUID()}`);
  name = input<string | null>(null);
  placeholder = input('');
  searchPlaceholder = input('');
  searchAriaLabel = input('');
  emptyText = input('');
  options = input<UiSelectOption[]>([]);

  required = input(false);
  disabled = input(false);

  optionalText = input('');
  showOptionalText = input(false);
  labelTooltip = input('');

  errorMessage = input('');
  showError = input(false);
  customClass = input('');

  size = input<'sm' | 'md'>('md');

  searchable = input(false);
  serverSearch = input(false);
  allowClear = input(false);
  clearAriaLabel = input('');
  multiple = input(false);
  removeChipAriaLabel = input('Remover');

  valueChange = output<string | string[]>();
  searchChange = output<string>();

  /** Valor controlado externamente (one-way). */
  selectedValue = input<string | number | string[] | null>(null, {
    alias: 'value',
  });

  value = signal('');
  values = signal<string[]>([]);
  searchTerm = signal('');
  opened = signal(false);
  disabledState = signal(false);
  dropdownStyle = signal<Record<string, string> | null>(null);

  constructor() {
    if (this.ngControl) {
      this.ngControl.valueAccessor = this;
    }

    effect(() => {
      const external = this.selectedValue();
      if (external == null) return;

      if (this.multiple()) {
        const next = Array.isArray(external)
          ? external.map(String)
          : [String(external)];
        if (!this.sameStringArrays(next, this.values())) {
          this.values.set(next);
        }
        return;
      }

      const next = String(external);
      if (next !== this.value()) {
        this.value.set(next);
      }
    });
  }

  isDisabled = computed(() => this.disabled() || this.disabledState());

  errorId = computed(() => `${this.id()}-error`);
  labelId = computed(() => `${this.id()}-label`);
  labelTooltipId = computed(() =>
    this.labelTooltip().trim() ? `${this.labelId()}-tooltip` : null,
  );
  listboxId = computed(() => `${this.id()}-listbox`);

  chevronIcon = computed<UiIconName>(() =>
    this.opened() ? 'chevron-up' : 'chevron-down',
  );

  selectAriaLabel = computed(() => {
    if ((this.label() && !this.hideLabel()) || this.formField?.labelId()) {
      return null;
    }

    return this.ariaLabel();
  });

  selectAriaLabelledBy = computed(() => {
    if (this.label() && !this.hideLabel()) {
      return this.labelId();
    }

    return this.formField?.labelId() ?? null;
  });

  describedBy = computed(() => {
    if (this.formField) {
      return this.formField.describedBy();
    }

    const ids = [
      this.labelTooltip().trim() && this.label() && !this.hideLabel()
        ? this.labelTooltipId()
        : null,
      this.hasError() ? this.errorId() : null,
    ].filter(Boolean);

    return ids.length ? ids.join(' ') : null;
  });

  selectedOption = computed(
    () =>
      this.options().find((option) => option.value === this.value()) ?? null,
  );

  selectedLabel = computed(() => this.selectedOption()?.label ?? '');

  selectedOptions = computed(() => {
    const selected = new Set(this.values());
    return this.options().filter((option) => selected.has(option.value));
  });

  hasSelection = computed(() =>
    this.multiple() ? this.values().length > 0 : Boolean(this.value()),
  );

  visibleOptions = computed(() => {
    if (this.serverSearch()) return this.options();

    const term = this.searchTerm().trim().toLowerCase();
    if (!term) return this.options();

    return this.options().filter((option) =>
      option.label.toLowerCase().includes(term),
    );
  });

  classes = computed(() =>
    [
      'ui-select',
      `ui-select--${this.size()}`,
      this.multiple() ? 'ui-select--multiple' : '',
      this.hasError() ? 'ui-select--error' : '',
      this.isDisabled() ? 'ui-select--disabled' : '',
      this.opened() ? 'ui-select--open' : '',
      !this.hasSelection() ? 'ui-select--placeholder' : '',
      this.allowClear() && this.hasSelection() ? 'ui-select--clearable' : '',
      this.customClass(),
    ]
      .filter(Boolean)
      .join(' '),
  );

  hasRequired(): boolean {
    const control = this.ngControl?.control;

    return Boolean(
      this.required() || control?.hasValidator?.(Validators.required),
    );
  }

  hasError(): boolean {
    if (this.formField) {
      return this.formField.hasError();
    }

    const control = this.ngControl?.control;

    return Boolean(
      this.showError() ||
        (control?.invalid && (control.touched || control.dirty)),
    );
  }

  isOptionSelected(option: UiSelectOption): boolean {
    if (this.multiple()) {
      return this.values().includes(option.value);
    }

    return option.value === this.value();
  }

  onChange: (value: string | string[]) => void = () => {};
  onTouched: () => void = () => {};

  toggle(): void {
    if (this.isDisabled()) return;

    const next = !this.opened();
    this.opened.set(next);

    if (next) {
      this.updateDropdownPosition();
      if (this.searchable()) {
        queueMicrotask(() => this.searchInput()?.nativeElement.focus());
      }
    } else {
      this.dropdownStyle.set(null);
      this.searchTerm.set('');
    }
  }

  close(): void {
    this.opened.set(false);
    this.searchTerm.set('');
    this.dropdownStyle.set(null);
  }

  private updateDropdownPosition(): void {
    const trigger = this.host.nativeElement.querySelector(
      '.ui-select__trigger',
    ) as HTMLElement | null;
    if (!trigger) return;

    const rect = trigger.getBoundingClientRect();
    const dropdownMax = 280;
    const gap = 6;
    const spaceBelow = window.innerHeight - rect.bottom;
    const openUp = spaceBelow < dropdownMax && rect.top > spaceBelow;

    const style: Record<string, string> = {
      position: 'fixed',
      left: `${Math.max(8, rect.left)}px`,
      width: `${Math.max(rect.width, 160)}px`,
      right: 'auto',
      zIndex: '10000',
    };

    if (openUp) {
      style['bottom'] = `${Math.max(8, window.innerHeight - rect.top + gap)}px`;
      style['top'] = 'auto';
    } else {
      style['top'] = `${rect.bottom + gap}px`;
      style['bottom'] = 'auto';
    }

    this.dropdownStyle.set(style);
  }

  selectOption(option: UiSelectOption): void {
    if (this.isDisabled() || option.disabled) return;

    if (this.multiple()) {
      const current = this.values();
      const next = current.includes(option.value)
        ? current.filter((value) => value !== option.value)
        : [...current, option.value];

      this.values.set(next);
      this.onChange(next);
      this.valueChange.emit(next);
      this.updateDropdownPosition();
      return;
    }

    this.value.set(option.value);
    this.onChange(option.value);
    this.valueChange.emit(option.value);
    this.close();
  }

  removeChip(option: UiSelectOption, event: MouseEvent): void {
    event.preventDefault();
    event.stopPropagation();

    if (this.isDisabled() || !this.multiple()) return;

    const next = this.values().filter((value) => value !== option.value);
    this.values.set(next);
    this.onChange(next);
    this.valueChange.emit(next);

    if (this.opened()) {
      this.updateDropdownPosition();
    }
  }

  clearValue(event: MouseEvent): void {
    event.preventDefault();
    event.stopPropagation();

    if (this.isDisabled()) return;

    if (this.multiple()) {
      this.values.set([]);
      this.onChange([]);
      this.valueChange.emit([]);
    } else {
      this.value.set('');
      this.onChange('');
      this.valueChange.emit('');
    }

    this.searchTerm.set('');
    this.close();
  }

  handleSearch(event: Event): void {
    const value = (event.target as HTMLInputElement).value;

    this.searchTerm.set(value);
    this.searchChange.emit(value);
  }

  handleBlur(): void {
    this.onTouched();
  }

  writeValue(value: UiSelectValue): void {
    if (this.multiple()) {
      if (Array.isArray(value)) {
        this.values.set(value.map(String));
        return;
      }

      if (value == null || value === '') {
        this.values.set([]);
        return;
      }

      this.values.set([String(value)]);
      return;
    }

    this.value.set(value == null ? '' : String(value));
  }

  registerOnChange(fn: (value: string | string[]) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabledState.set(isDisabled);
  }

  @HostListener('document:click', ['$event'])
  onDocumentClick(event: MouseEvent): void {
    const target = event.target as Node | null;
    if (!target) return;

    if (!this.host.nativeElement.contains(target)) {
      this.close();
    }
  }

  @HostListener('window:resize')
  onViewportChange(): void {
    if (!this.opened()) return;
    this.updateDropdownPosition();
  }

  @HostListener('document:scroll', ['$event'])
  onDocumentScroll(): void {
    if (this.opened()) this.close();
  }

  @HostListener('keydown.escape')
  onEscape(): void {
    this.close();
  }

  private sameStringArrays(a: string[], b: string[]): boolean {
    if (a.length !== b.length) return false;
    return a.every((value, index) => value === b[index]);
  }
}

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
  output,
  ViewEncapsulation,
} from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { UiEmptyStateComponent } from '../empty-state/ui-empty-state.component';
import { UiIconComponent, UiIconName } from '../icon/ui-icon.component';
import { UiPaginationComponent } from '../pagination/ui-pagination.component';
import { UiBadgeType } from '../badge/ui-badge.component';

export type UiTableSortDir = 'asc' | 'desc';
export type UiTableAlign = 'left' | 'center' | 'right';
export type UiTableSize = 'sm' | 'md' | 'lg';
export type UiTablePaginationPosition = 'top' | 'bottom' | 'both';

/** Breakpoints: mobile < 768px, tablet 768–1023px, desktop ≥ 1024px */
export type UiTableBreakpoint = 'mobile' | 'tablet';

export type UiTableColumnBadgeValue =
  | UiBadgeType
  | {
      label?: string;
      type?: UiBadgeType;
    };

export interface UiTableColumnBadge {
  map?: Record<string, UiTableColumnBadgeValue>;
  defaultType?: UiBadgeType;
}

export interface UiTableColumn {
  key: string;
  label: string;
  sortable?: boolean;
  /**
   * Hide this column on the given breakpoints.
   * - `mobile`: hidden below 768px
   * - `tablet`: hidden between 768px and 1023px
   * Use `['mobile', 'tablet']` to show only on desktop (≥1024px).
   */
  hideOn?: UiTableBreakpoint[];
  /** @deprecated Prefer `hideOn: ['mobile']` */
  hideMobile?: boolean;
  width?: string;
  minWidth?: string;
  align?: UiTableAlign;
  headerAlign?: UiTableAlign;
  isActions?: boolean;
  badge?: UiTableColumnBadge;
}

