import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  HostListener,
  computed,
  inject,
  input,
  signal,
} from '@angular/core';
import {
  UiIconComponent,
  UiIconName,
  UiIconSize,
} from '../icon/ui-icon.component';

export type UiTooltipPosition = 'top' | 'right' | 'bottom' | 'left';

type TooltipCoords = {
  top: string;
  left: string;
};

@Component({
  selector: 'ui-tooltip',
  standalone: true,
  imports: [UiIconComponent],
  templateUrl: './ui-tooltip.component.html',
  styleUrl: './ui-tooltip.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class UiTooltipComponent {
  private readonly hostRef = inject<ElementRef<HTMLElement>>(ElementRef);

  text = input('');
  html = input<string | null>(null);
  position = input<UiTooltipPosition>('top');
  disabled = input(false);
  maxWidth = input('240px');
  delay = input('0ms');
  customClass = input('');

  icon = input<UiIconName | null>(null);
  iconSize = input<UiIconSize>('sm');
  iconColor = input<string | null>(null);
  iconLabel = input('');

  private readonly fallbackTooltipId = `ui-tooltip-${crypto.randomUUID()}`;
  id = input<string | null>(null);

  readonly visible = signal(false);
  readonly coords = signal<TooltipCoords | null>(null);

  resolvedTooltipId = computed(
    () => this.id()?.trim() || this.fallbackTooltipId,
  );

  resolvedIconLabel = computed(() => {
    const label = this.iconLabel().trim();
    if (label) {
      return label;
    }

    return this.text().trim() || null;
  });

  tooltipClasses = computed(() =>
    [
      'ui-tooltip__content',
      `ui-tooltip__content--${this.position()}`,
      'ui-tooltip__content--fixed',
      this.visible() ? 'ui-tooltip__content--visible' : '',
      this.disabled() ? 'ui-tooltip__content--disabled' : '',
      this.customClass(),
    ]
      .filter(Boolean)
      .join(' '),
  );

  @HostListener('mouseenter')
  @HostListener('focusin')
  onShow(): void {
    if (this.disabled()) {
      return;
    }

    this.coords.set(this.computeCoords());
    this.visible.set(true);
  }

  @HostListener('mouseleave')
  onMouseLeave(): void {
    this.hide();
  }

  @HostListener('focusout', ['$event'])
  onFocusOut(event: FocusEvent): void {
    const host = this.hostRef.nativeElement;
    const nextTarget = event.relatedTarget as Node | null;

    if (nextTarget && host.contains(nextTarget)) {
      return;
    }

    this.hide();
  }

  private hide(): void {
    this.visible.set(false);
    this.coords.set(null);
  }

  private computeCoords(): TooltipCoords {
    const host = this.hostRef.nativeElement.getBoundingClientRect();
    const gap = 8;

    switch (this.position()) {
      case 'bottom':
        return {
          top: `${host.bottom + gap}px`,
          left: `${host.left + host.width / 2}px`,
        };
      case 'left':
        return {
          top: `${host.top + host.height / 2}px`,
          left: `${host.left - gap}px`,
        };
      case 'right':
        return {
          top: `${host.top + host.height / 2}px`,
          left: `${host.right + gap}px`,
        };
      case 'top':
      default:
        return {
          top: `${host.top - gap}px`,
          left: `${host.left + host.width / 2}px`,
        };
    }
  }
}

